// === Tab: mySketch.js ===
let bg; // 离屏画布：先在这里画 3D 图形，再把它转换成粒子效果

function setup() {
	  initCanvas(); // 创建主画布
  bg = createGraphics(90, 160, WEBGL); // 创建一个 9:16 的隐藏 3D 画布
}

function draw() {
  bg.clear(); // 清空上一帧的离屏画布
  bg.background(255); // 给离屏画布设置白色背景

  bg.push();
  bg.noStroke(); // 不画 3D 模型的网格线，这样粒子不会连成线
  bg.ambientLight(180); // 环境光，让暗面不会完全变黑
  bg.pointLight(180, 120, 120, 50, 0, -1); // 点光源，用来制造柔和的 3D 明暗
  bg.rotateX(millis() / 1000); // 随时间绕 X 轴旋转
  bg.rotateY(millis() / 1000); // 随时间绕 Y 轴旋转
  bg.rotateZ(millis() / 1000); // 随时间绕 Z 轴旋转
  bg.scale(0.70); // 缩小一点，避免图形贴到画布边缘
  bg.torus(35, 12); // 画一个 3D 圆环
  let frameImage = bg.get(); // 把离屏画布当前画面截取成一张图片
  bg.pop();

  makeDithered(frameImage, 1); // 把图片转换成黑白抖动效果

  background(0); // 清空主画布，并设置成黑色背景
  drawParticlesFromImage(frameImage); // 根据抖动后的图片画出粒子
}

function drawParticlesFromImage(img) {
  push();
  img.loadPixels(); // 读取图片的像素数据

  const wscale = width / img.width; // 把小图片的 x 坐标放大到主画布
  const hscale = height / img.height; // 把小图片的 y 坐标放大到主画布
  const thresh = 245; // 灰度阈值：小于这个值的像素都会被画成点
  const sampleStep = 1; // 每隔 2 个像素取样一次，让点点更稀疏

  for (let y = 0; y < img.height; y += sampleStep) {
    for (let x = 0; x < img.width; x += sampleStep) {
      const col = getColorAtIndex(img, x, y); // 取得当前像素颜色
      const gray = getGrayscale(col); // 把颜色转换成灰度值

      if (gray < thresh) {
        noStroke();
        fill(255); // 在黑色背景上画白色粒子
        circle(
          x * wscale, // 粒子在主画布上的 x 位置
          y * hscale, // 粒子在主画布上的 y 位置
          wscale * 1.25 * map(gray, 0, 255, 1, 0) // 越黑的像素，圆点越大
        );
      }
    }
  }

  pop();
}

function getGrayscale(c) {
  return round(red(c) * 0.222 + green(c) * 0.707 + blue(c) * 0.071); // 按人眼敏感度计算灰度
}

function initCanvas() {
  const size = getVerticalCanvasSize(); // 计算适合窗口的 9:16 画布尺寸

  createCanvas(size.w, size.h); // 创建 9:16 竖版主画布
}

function windowResized() {
  var size = getVerticalCanvasSize(); // 窗口变化时重新计算 9:16 画布尺寸

  resizeCanvas(size.w, size.h); // 调整主画布大小
}

function getVerticalCanvasSize() {
  const margin = 0.9; // 使用窗口 90% 的空间，留一点边距
  let canvasH = windowHeight * margin;
  let canvasW = canvasH * 9 / 16;

  if (canvasW > windowWidth * margin) {
    canvasW = windowWidth * margin;
    canvasH = canvasW * 16 / 9;
  }

  return {
    w: canvasW,
    h: canvasH
  };
}

function keyPressed() {
  if (key === 's') {
    saveCanvas('sphere-dither-particles', 'png'); // 按 s 键保存图片
  }
}

function imageIndex(img, x, y) {
  return 4 * (x + y * img.width); // 每个像素有 R、G、B、A 四个数值
}

function getColorAtIndex(img, x, y) {
  const idx = imageIndex(img, x, y); // 找到当前像素在 pixels 数组里的起始位置
  const pix = img.pixels;
  const r = pix[idx]; // 红色通道
  const g = pix[idx + 1]; // 绿色通道
  const b = pix[idx + 2]; // 蓝色通道
  const a = pix[idx + 3]; // 透明度通道

  return color(r, g, b, a); // 返回 p5.js 的颜色对象
}

function setColorAtIndex(img, x, y, clr) {
  var idx = imageIndex(img, x, y); // 找到要写入的像素位置
  var pix = img.pixels;

  pix[idx] = red(clr); // 写入红色通道
  pix[idx + 1] = green(clr); // 写入绿色通道
  pix[idx + 2] = blue(clr); // 写入蓝色通道
  pix[idx + 3] = alpha(clr); // 写入透明度通道
}

function closestStep(max, steps, value) {
  return round((steps * value) / max) * floor(max / steps); // 把颜色值压缩到最接近的色阶
}

function makeDithered(img, steps) {
  img.loadPixels(); // 开始读取并修改图片像素

  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      const clr = getColorAtIndex(img, x, y); // 读取当前像素颜色
      const oldR = red(clr); // 原始红色值
      const oldG = green(clr); // 原始绿色值
      const oldB = blue(clr); // 原始蓝色值
      const newR = closestStep(255, steps, oldR); // 量化后的红色值
      const newG = closestStep(255, steps, oldG); // 量化后的绿色值
      const newB = closestStep(255, steps, oldB); // 量化后的蓝色值
      const newClr = color(newR, newG, newB); // 新的简化颜色

      setColorAtIndex(img, x, y, newClr); // 把当前像素改成量化后的颜色

      distributeError(img, x, y, oldR - newR, oldG - newG, oldB - newB); // 把颜色误差扩散给周围像素
    }
  }

  img.updatePixels(); // 把修改后的像素写回图片
}

function distributeError(img, x, y, errR, errG, errB) {
  addError(img, 7 / 16, x + 1, y, errR, errG, errB); // 右边像素得到 7/16 的误差
  addError(img, 3 / 16, x - 1, y + 1, errR, errG, errB); // 左下像素得到 3/16 的误差
  addError(img, 5 / 16, x, y + 1, errR, errG, errB); // 正下方像素得到 5/16 的误差
  addError(img, 1 / 16, x + 1, y + 1, errR, errG, errB); // 右下像素得到 1/16 的误差
}

function addError(img, factor, x, y, errR, errG, errB) {
  if (x < 0 || x >= img.width || y < 0 || y >= img.height) {
    return; // 如果超出图片边界，就不处理
  }

  var clr = getColorAtIndex(img, x, y); // 读取邻近像素

  clr.setRed(red(clr) + errR * factor); // 加上按比例分配的红色误差
  clr.setGreen(green(clr) + errG * factor); // 加上按比例分配的绿色误差
  clr.setBlue(blue(clr) + errB * factor); // 加上按比例分配的蓝色误差

  setColorAtIndex(img, x, y, clr); // 写回修改后的邻近像素
}

